function next(n){if(busy||!chapters[n])return;busy=true;hideHot();choices([]);hint('');$('curtain').style.opacity=1;sound('wind');after(.65,()=>{clear();chapter=n;st.chapter=n;save();let c=chapters[n];$('chapter').textContent=c.year+' · '+c.age+' · '+c.name;c.build();score(c.score,c.at,c.gain);let initial=$('subtitle').textContent;say(c.context);after(4.2,()=>{if($('subtitle').textContent===c.context)say(initial);});let year=glyph(c.year,0,3.8,-12,6,n>=8?BLUE:GOLD);year.userData.alpha=.34;after(3.5,()=>tween(year.userData,{scatter:.7,alpha:0},2.5));$('curtain').style.opacity=0;});}
function prologue(){clear();mode='prologue';chapter=-1;st.chapter=0;try{localStorage.setItem('river-particle-v4',JSON.stringify(st));}catch{}$('chapter').textContent='此刻';score(0,9,.24);let phone=form('rotary',0,.4,-2,5,GOLD,8500);phone.userData.alpha=.35;let echo=glyph('稳',0,3.4,-3,3.6,GOLD);echo.userData.scatter=.65;reveal(echo,3);camera.position.set(0,1.6,10);look.set(0,1,-3);fly(V(0,1.6,7),V(0,1,-3),3);sound('ring');say('“别折腾。”');hint('点亮这句话。');hot(echo,'听见','enter-memory',()=>{busy=true;hideHot();say('');hint('');tween(echo.userData,{scatter:1.3,alpha:0},2.5);tween(phone.userData,{scatter:.9,alpha:0},2.5);fly(V(0,1.6,1),V(0,1,-6),2.8,()=>{busy=false;next(0);});},-1.2);}
let grain={};function grainScene(){mode='grain';lightBeam(V(2,4,-9),V(-1,-.6,9),1.2,0xd7bf91);grain={ticket:false,cash:false,queue:3,phase:0,waiting:false,meal:[0,0],amount:6};let clerk=form('person',0,2,-9,4,GOLD,5500);clerk.userData.alpha=.35;for(let i=0;i<3;i++){let p=form('person',i%2?.25:-.3,1.6,4-i*3.5,4.4,0xafa07e,6500);p.userData.alpha=.6;grain['person'+i]=p;}let room=[];for(let i=0;i<15000;i++){let side=i%2?-1:1;room.push(side*(3.5+rand()*.5),rand()*4.4-.8,rand()*24-10);}let walls=points(room,0x80745c,.022);walls.userData.alpha=.24;let roof=[];for(let i=0;i<5000;i++)roof.push((rand()-.5)*7,4+rand()*.25,rand()*24-10);points(roof,0xb0a187,.016).userData.alpha=.16;let shelf=[];for(let i=0;i<5000;i++)shelf.push((rand()-.5)*7,-.2+rand()*3,-8+(rand()-.5)*.2);let window=points(shelf,0x8c744b,.025);window.userData.alpha=.14;grain.ticketActor=form('ticket',1.1,1.25,8.1,1.8,GOLD,4300);grain.cashActor=form('money',-1.1,.65,8.1,1.8,GOLD,2800);grain.hand=form('grip',.65,.95,8.1,2.2,GOLD,8500);grain.hand.userData.alpha=.1;grain.bag=form('sack',.8,1.1,-6,2.4,GOLD,1900);grain.bag.userData.alpha=.58;hot(grain.ticketActor,'拿票','take-ticket',pickTicket,-.8);hot(grain.cashActor,'钱','pay-money',pay,-.8);hot(grain.bag,'窗口','window',queueForward,-.8);camera.position.set(0,1.6,14);look.set(0,1.1,-4);fly(V(0,1.65,11),V(0,1.3,-6),4);say('前面，还有三个人。');hint('点击票和钱，准备好再等窗口。');let dust=[];for(let i=0;i<2200;i++)dust.push((rand()-.5)*9,rand()*4,rand()*17-5);let air=points(dust,0xad9e86,.015);air.userData.alpha=.14;anim.push({tick(t){air.rotation.z=Math.sin(t*.035)*.018;return false;}});grain.started=time;}
function pickTicket(){if(grain.ticket)return;grain.ticket=true;grain.hand.userData.alpha=.9;sound('paper');hotspots.find(h=>h.b.dataset.action==='take-ticket').b.style.display='none';grain.ticketActor.rotation.z=-.12;move(grain.ticketActor,V(1.05,1.25,8.3),1.4);reveal(grain.hand,1.4);say('攥紧了。别弄丢。');hint('还需要付款的钱。');}
function pay(){if(grain.cash)return;grain.cash=true;sound('coin');hotspots.find(h=>h.b.dataset.action==='pay-money').b.style.display='none';move(grain.cashActor,V(.7,.9,8.35),1.2);grain.cashActor.scale.setScalar(.6);say('票和钱，一样不能少。');hint('点窗口，等叫到下一位。');}
function queueForward(){if(grain.phase>0)return;if(!grain.ticket||!grain.cash){say(!grain.ticket?'没有票，还不能领。':'有票，也要付钱。');sound('dull');return;}if(grain.waiting)return;if(grain.queue>0){grain.waiting=true;hint('等窗口叫到下一位。');sound('stamp');let i=3-grain.queue;let p=grain['person'+i];tween(p.userData,{scatter:.8,alpha:0},3);after(2.2,()=>{if(chapter!==0||grain.phase>0)return;grain.queue--;let z=11-(3-grain.queue)*3;fly(V(0,1.65,z),V(0,1.3,-6),3,()=>{grain.waiting=false;grain.ticketActor.position.z=z-2.6;grain.hand.position.z=z-2.5;grain.cashActor.position.z=z-2.55;say(grain.queue?['','前面，还有一个人。','前面，还有两个人。'][grain.queue]:'轮到你了。');hint(grain.queue?'点窗口，向前挪一步。':'按住票，把它递到窗口。');if(!grain.queue){hotspots.find(h=>h.b.dataset.action==='window').b.style.display='none';prepareDeliver();}});sound('step');});} }
function prepareDeliver(){grain.phase=1;choices([]);let b=hot(grain.ticketActor,'按住递票','deliver-ticket',()=>beginDelivery(true),-.5);b.onpointerdown=e=>{e.preventDefault();b.setPointerCapture(e.pointerId);beginDelivery(false);};b.onpointerup=e=>{e.preventDefault();if(hold&&!hold.auto)cancelDelivery();};b.onpointercancel=cancelDelivery;b.onclick=e=>{if(e.detail===0)beginDelivery(true);};}
function beginDelivery(auto=false){if(grain.phase!==1||hold||paused||cam)return;hold={start:time,auto,origin:grain.ticketActor.position.clone()};hint('保持按住。让手里的票递过去。');sound('paper');let start=time;anim.push({tick(t){if(!hold||grain.phase!==1)return true;let k=clamp((t-start)/1.7);grain.ticketActor.position.lerpVectors(hold.origin,V(.1,1,-5.4),k*k);grain.hand.position.lerp(V(.5,.7,-4.5),.012);grain.ticketActor.userData.alpha=.7+k*.25;if(k>=1){hold=null;deliverTicket();return true;}return false;}});}
function cancelDelivery(){if(!hold||grain.phase!==1)return;grain.ticketActor.position.copy(hold.origin);hold=null;hint('按住票，递到窗口。');}
function deliverTicket(){if(grain.phase!==1)return;grain.phase=2;busy=true;hideHot();choices([]);musicLevel(.015,.8);sound('paper');say('手里的票，递了出去。');hint('等核验。');move(grain.ticketActor,V(0,.9,-5.5),2.2);move(grain.cashActor,V(.2,.6,-5.4),2.2);move(grain.hand,V(.5,.45,-4.2),2.2);fly(V(-.4,1.5,1),V(0,1,-6),3,()=>{sound('stamp');after(1.4,()=>musicLevel(.3,3));tween(grain.ticketActor.userData,{scatter:.7,alpha:0},1.2);tween(grain.cashActor.userData,{alpha:0},1);say('这一份，是一家人的口粮。');pour(V(.2,2.2,-6),V(.8,1.2,-6),1200,2,()=>{move(grain.bag,V(.6,.5,-1.2),2.5,()=>{busy=false;grain.phase=3;sound('grain');say('只领到这一袋。');hint('伸手接住，再带回家。');choices([['接住',takeBag],['再领一袋',()=>{sound('dull');say('票已经用掉了。');hint('手里没有下一份票。先接住这一袋。');}]]);});});});}
function pour(from,to,n,duration,done){let coords=[],start=time;for(let i=0;i<n;i++)coords.push(from.x+(rand()-.5)*.8,from.y,from.z+(rand()-.5)*.6);let p=points(coords,GOLD,.08);let attr=p.geometry.getAttribute('position');anim.push({tick(t){let k=(t-start)/duration;for(let i=0;i<n;i++){let f=clamp(k-(i/n)*.3),x=from.x+(to.x-from.x)*f,y=from.y+(to.y-from.y)*f-Math.sin(f*Math.PI)*.15,z=from.z+(to.z-from.z)*f;attr.setXYZ(i,x+(Math.sin(i*7)*.3)*(1-f*.7),y+Math.sin(i)*.18,z+Math.cos(i*9)*.2);}attr.needsUpdate=true;if(k>=1.3){tween(p.userData,{alpha:.12},1);if(done)done();return true;}}});return p;}
function takeBag(){busy=true;choices([]);sound('grain');move(grain.hand,V(.8,.1,-.9),1.5);move(grain.bag,V(.6,.35,-.8),1.5,()=>{say('带回去。还要想着明天。');tween(grain.hand.userData,{scatter:.6,alpha:0},2);tween(grain.bag.userData,{scatter:.5,alpha:0},2);fly(V(0,3,8),V(0,.2,0),3,mealScene);});}
function mealScene(){clear();mode='meal';grain.phase=4;let parent=form('person',-4,1,-5,4.5,GOLD,5500);parent.userData.alpha=.25;form('person',4,.9,-6,3.2,GOLD,3500).userData.alpha=.23;grain.source=form('sack',0,1,-2,2.6,GOLD,1400);grain.bowls=[form('bowl',-2.6,.1,0,3.4,GOLD,3800),form('bowl',2.6,.1,0,3.4,GOLD,3800)];grain.fills=[[],[]];hot(grain.bowls[0],'今晚','tonight',()=>measure(0),-.9);hot(grain.bowls[1],'明天','tomorrow',()=>measure(1),-.9);camera.position.set(0,3.4,8);look.set(0,.8,0);say('今晚吃多少，明天留多少？');hint('一袋分六份。点击两只碗，逐份舀进去。');grain.meal=[0,0];grain.amount=6;}
function measure(i){if(grain.amount<=0||busy)return;busy=true;grain.amount--;grain.meal[i]++;sound('grain');grain.source.scale.setScalar(.45+.55*grain.amount/6);let pos=grain.bowls[i].position;pour(V(0,1.6,-2),pos.clone().add(V(0,.08,0)),400,1.1,()=>{busy=false;if(!grain.amount){st.ration=grain.meal.slice();save();hideHot();say(grain.meal[1]?'留一点，明天还有。':'今晚吃完了。明天，怎么办？');hint('这是一段虚构的家庭记忆。');choices([['留在心里',()=>next(1)]]);}else hint(`还剩 ${grain.amount} 份。`);});}
function trainScene(){mode='train';lightBeam(V(-6,5,-8),V(4,-1,3),2,0xcfb993);let hand=form('hand',-2,-.8,4,3.2,GOLD,6500),bag=form('case',-2.4,-.2,2,3.4,GOLD,5500),train=form('train',-20,1,-4,11,GOLD,14000);hand.userData.alpha=.12;let paper=form('letter',3,.1,1,1.8,GOLD,2400);let platform=[];for(let i=0;i<4500;i++){let x=(rand()-.5)*55;platform.push(x,-1.2,-4+(rand()-.5)*.05);}points(platform,0xab946a,.032).userData.alpha=.38;let figures=[];for(let i=0;i<5;i++)figures.push(form('person',(i-2)*3,1.3,-10,3.5,GOLD,3200));let carry=false,letter=false,arrived=false;hot(bag,'提箱','carry-case',()=>{if(carry)return;carry=true;sound('step');reveal(hand,1);move(bag,V(-1.5,-.3,4),2);say('家，留在身后。');hint('可以留一封信。等车停稳，再上车。');},-.8);hot(paper,'留信','leave-letter',()=>{letter=true;sound('paper');tween(paper.userData,{scatter:.8,alpha:0},2);say('到了，给家里捎个信。');},-.6);hot(train,'上车','board-train',()=>{if(!carry){say('先提起自己的行李。');return;}if(!arrived){say('车还没停稳。');return;}hideHot();busy=true;sound('train');tween(bag.userData,{scatter:.5,alpha:0},2);tween(hand.userData,{alpha:0},2);fly(V(1,1.5,-3),V(8,1,-7),4,()=>{tween(train.userData,{scatter:.5,alpha:.12},5);figures.forEach(p=>tween(p.userData,{scatter:.4,alpha:0},5));let city=[];for(let i=0;i<12500;i++){let x=(rand()-.5)*35,cluster=Math.floor((x+17.5)/2),height=2+(cluster*17%9);city.push(x,rand()*height-1.1,-17+(rand()-.5)*.5);}let sky=points(city,GOLD,.027);reveal(sky,5);say(letter?'联系还在。路，要自己走。':'你离开了，他们仍会担心。');fly(V(0,2,7),V(0,3,-16),6,()=>{busy=false;choices([['往前走',()=>next(3)]]);});});},-.8);camera.position.set(0,1.5,10);look.set(0,.8,-4);fly(V(0,1.6,7),V(0,1,-4),3);move(train,V(1,1,-4),7,()=>{arrived=true;sound('train');});sound('train');say('第一次出远门。');hint('提起箱子。列车正在进站。');}
function keyScene(){mode='key';corridor(15,24);lightBeam(V(5,3.5,-7),V(1,-.5,2),1.2,0xe3b773);let key=form('key',0,.1,3,2.7,GOLD,5200),door=form('door',4,1,-5,5.5,GOLD,8000);key.userData.alpha=.1;let coins=[];for(let i=0;i<12;i++){let p=form('money',(i%6-2.5)*.75,1.6-Math.floor(i/6)*.7,-1,1.05,GOLD,300);coins.push(p);}let allocated=false,taken=false;let wall=glyph('家',4,1,-8,3.3,GOLD);wall.userData.alpha=.16;camera.position.set(0,2.2,13);look.set(0,1,-4);fly(V(0,1.7,9),V(0,1,-3),4);say('成家之后，手里的钱要分给很多明天。');hint('这些光点，是一家人的余量。');choices([['把更多钱放进房子',()=>allocate('home',10)],['住小一点，留一些余量',()=>allocate('margin',7)]]);function allocate(kind,n){if(allocated)return;allocated=true;busy=true;st.path=kind;choices([]);sound('paper');coins.slice(0,n).forEach((p,i)=>after(i*.12,()=>move(p,V(4,.2,-5),1.8,()=>tween(p.userData,{scatter:.25,alpha:0},1))));after(3,()=>{busy=false;reveal(key,1.5);say(kind==='home'?'家安稳了。手里的余量，也少了。':'住处小一些。还有应对明天的余量。');hint('拿起钥匙，打开这扇门。');});}hot(key,'拿钥匙','take-key',()=>{if(!allocated){say('先决定，给住处留多少。');return;}taken=true;sound('key');move(key,V(2,.2,3),1.6);say('钥匙很轻，责任很重。');},-1);hot(door,'开门','open-house',()=>{if(!taken){say('钥匙还不在手里。');return;}busy=true;hideHot();choices([]);sound('key');move(key,V(4.5,.7,-4.9),2);fly(V(3,1.6,1),V(5,1,-5),3,()=>{tween(door.userData,{scatter:1.1,alpha:.1},4);tween(key.userData,{alpha:0},2);let warm=[];for(let i=0;i<9000;i++){let a=rand()*Math.PI*2,r=Math.sqrt(rand())*5;warm.push(5+Math.cos(a)*r,.5+Math.sin(a)*r*.55,-7+(rand()-.5)*3);}let p=points(warm,0xdea868,.027);reveal(p,4);fly(V(5,1.6,-3),V(5,1,-7),5,()=>{busy=false;say('从此，担心的不只自己。');hint('一扇门里，还有一个正在长大的孩子。');choices([['往后的日子',()=>next(5)]]);});});},-2);}
function nowScene(){mode='now';let phone=form('phone',-4,1,-1,3.8,BLUE,5000),clock=form('clock',0,1,-4,3.4,GOLD,6000),breath=form('breath',4,1,-1,4,GOLD,5000);let feed=[];for(let i=0;i<15;i++){let p=glyph(['还有消息','别人更快','不能停'][i%3],(rand()-.5)*16,rand()*5,-6-rand()*8,3,BLUE);p.userData.alpha=.3;feed.push(p);}let quiet=false,rest=false,applications=0;hot(phone,'投递','send-application',()=>{if(quiet)return;applications++;sound('paper');let result=glyph(applications%2?'待回复':'未通过',0,2,-3,3.2,BLUE);reveal(result,.6);after(2,()=>tween(result.userData,{scatter:.8,alpha:0},2));say(applications===1?'投出去了。结果，还不由你决定。':'努力是真的，不确定也是真的。');if(applications>=2){hotspots.find(h=>h.b.dataset.action==='send-application').b.style.display='none';quietButton.style.display='block';hint('给今天的自己，留一个暂停。');}},-.1);anim.push({tick(t){if(!quiet)feed.forEach((p,i)=>p.position.x+=Math.sin(t+i)*.004);return false;}});let quietButton=hot(phone,'静音','quiet-phone',()=>{quiet=true;sound('off');feed.forEach(p=>tween(p.userData,{scatter:1,alpha:0},2.5));phone.userData.alpha=.16;say('先让消息，安静一会儿。');hint('你的注意力，也属于你。');},-1.4);quietButton.style.display='none';hot(clock,'休息','rest-clock',()=>{if(!quiet){say('消息，还在占着你的时间。');return;}rest=true;sound('breath');clock.rotation.z=-.2;tween(clock.userData,{scatter:.3,alpha:.22},2);say('不用耗尽自己，证明努力。');hint('再找回自己的节奏。');},-1.5);hot(breath,'自己的节奏','own-step',()=>{if(!rest){say('先留一点休息。');return;}hideHot();reveal(breath,2);say('机会更多，确定的答案却未必更多。');hint('下一步，不必等所有人认可。');choices([['拿回自己的日子',()=>next(9)]]);},-1.4);camera.position.set(0,2,13);look.set(0,1,-3);fly(V(0,1.8,9),V(0,1,-3),4);say('消息更快。比较更近。');hint('点击投递。把机会交出去，也看见不确定。');}
let phoneTurn=0;function phoneScene(){mode='call';lightBeam(V(-3,3,-8),V(2,-.7,1),1.6,GOLD);form('person',-5,1,-7,4,GOLD,6000).userData.alpha=.35;form('person',5,1,-7,4,BLUE,6000).userData.alpha=.35;let phone=form('rotary',0,.4,-1,5,GOLD,9000);let link=[];for(let i=0;i<5000;i++){let x=(rand()-.5)*12;link.push(x,.4+Math.sin(x)*.08,-4+Math.sin(x*.4));}points(link,GOLD,.03).userData.alpha=.35;camera.position.set(0,1.5,10);look.set(0,.8,-2);fly(V(0,1.7,7),V(0,.8,-2),3);sound('ring');phoneTurn=0;say('“我是怕你吃亏。”');hint('你想怎样回答？');phoneChoices();}
function phoneChoices(){if(phoneTurn===0)choices([['先听完',()=>answer('listen')],['解释处境',()=>answer('facts')],['不想再争',()=>answer('pause')]]);if(phoneTurn===1)choices([['决定自己承担',()=>answer('own')],['商量有限支持',()=>answer('support')],['必须让他理解',()=>answer('force')]]);}
function answer(kind){sound('answer');if(kind==='force'){say('有些想法，今天仍改变不了。');hint('可以选择继续沟通，也可以先保护自己。');choices([['先过好自己的生活',()=>answer('own')],['留一点沟通',()=>answer('support')]]);return;}if(phoneTurn===0){phoneTurn=1;st.boundary=kind;fly(V(kind==='pause'?3:-3,1.7,7),V(0,1,-4),3);say(kind==='pause'?'“我们先停一会儿。”':kind==='facts'?'“我也担心，我有自己的处境。”':'“我听见你的担心了。”');hint('听见，不等于必须同意。');phoneChoices();}else{st.decision=kind;say(kind==='own'?'“这一步，我来承担。”':'“能支持多少，我们说具体。”');hint('父母未必改变。生活仍要继续。');choices([['把日子握回手里',()=>next(10)]]);}}
function endScene(){mode='end';let a=form('person',-5,1,-5,4.6,GOLD,9000),b=form('person',5,1,-5,4.6,BLUE,9000);a.userData.alpha=b.userData.alpha=.35;['省','稳','家'].forEach((t,i)=>glyph(t,-5,2.1-i*.8,-4.75,.68,GOLD));['选','界','我'].forEach((t,i)=>glyph(t,5,2.1-i*.8,-4.75,.68,BLUE));let river=[];for(let i=0;i<16000;i++){let x=(rand()-.5)*13;river.push(x,-.5+Math.sin(x*.4)*.16,-3+(rand()-.5)*1.4);}let r=points(river,GOLD,.023);r.userData.alpha=.42;let clock=form('clock',-2.8,.5,1,2.1,BLUE,4800),margin=form('money',0,.4,1,1.7,GOLD,3200),phone=form('phone',2.8,.5,1,2.1,BLUE,4700);let chosen=false;function choose(kind){if(chosen)return;chosen=true;st.future=kind;save();hideHot();busy=true;[clock,margin,phone].forEach(p=>tween(p.userData,{scatter:.7,alpha:0},3));say(kind==='time'?'给自己留时间。':'reserve'===kind?'给生活留一点余量。':'把边界说清楚。');hint('');let path=[];for(let i=0;i<17000;i++){let k=rand(),width=.15+k*1.1;path.push(5+Math.sin(k*3.14)*4+(rand()-.5)*width,-1+(rand()-.5)*.1,-5-k*35);}let road=points(path,BLUE,.026);reveal(road,4);fly(V(1,2.3,12),V(5,0,-11),5,()=>{say('有些想法，你改变不了。');after(4,()=>{say('但日子，可以自己过。');fly(V(0,4,20),V(4,.4,-12),8);after(7.5,()=>{busy=false;say('如果他们始终不理解，你会怎样过好自己的生活？');hint('');choices([['再走一遍',()=>{st={chapter:0,ration:[0,0],path:'',boundary:'',decision:''};prologue();}],['音乐与资料',showSources]]);});});});}hot(clock,'留时间','future-time',()=>choose('time'),-.8);hot(margin,'留余量','future-reserve',()=>choose('reserve'),-.8);hot(phone,'说边界','future-boundary',()=>choose('boundary'),-.8);camera.position.set(0,1.7,11);look.set(0,.8,-4);fly(V(0,2.4,13),V(0,1,-4),4);say('理解他们从哪里来。决定自己往哪里去。');hint('你想先为自己留住什么？');save();}
function showSources(){let wasPaused=paused;if(!paused)pause(true);$('sources').style.display='flex';$('sources').innerHTML=`<div class="credits-inner"><button id="closeCredits" aria-label="关闭资料">×</button><h2>音乐与时代依据</h2><p>人物以1975年出生为示意；孩子以2003年出生为示意。家庭故事为虚构，各地、城乡与家庭经历不同。</p><h3>Music by Scott Buckley</h3><p>'Signal to Noise', 'Signal to Noise — No Piano Melody', 'Undertow', 'Penumbra' by Scott Buckley — released under CC-BY 4.0.<br><a target="_blank" rel="noopener" href="https://www.scottbuckley.com.au">www.scottbuckley.com.au</a> · <a target="_blank" rel="noopener" href="https://creativecommons.org/licenses/by/4.0/">CC BY 4.0</a><br>游戏做了片段进入、音量包络与交叉淡化。</p><p>电话、列车：Joseph SARDIN / BigSoundBank（CC0）；纸张：alec_mackay / Freesound（CC0）；转盘电话：alexdarek / Freesound（CC0）。转场等取自HyperFrames媒体库（Pixabay Content License）。声音为戏剧化配置，不是中国历史现场录音。</p><h3>时间线</h3><p><a target="_blank" rel="noopener" href="https://www.mof.gov.cn/zhuantihuigu/czgg0000_1/czgg0000/200811/t20081106_88273.htm">票证与1993年粮食供应变化</a><br><a target="_blank" rel="noopener" href="https://www.moe.gov.cn/jyb_xwfb/xw_zt/moe_357/s3581/moe_2669/moe_2921/tnull_51639.html">1986年九年义务教育推行</a><br><a target="_blank" rel="noopener" href="https://www.gov.cn/gongbao/content/2003/content_62011.htm">1998年以来国企改革与再就业</a><br><a target="_blank" rel="noopener" href="https://www.gov.cn/gongbao/shuju/1998/gwyb199817.pdf">1998年住房制度改革</a><br><a target="_blank" rel="noopener" href="https://www.stats.gov.cn/sj/zxfb/202303/t20230301_1919494.html">2008年金融危机背景</a><br><a target="_blank" rel="noopener" href="https://www.cac.gov.cn/2016-01/22/c_1117853351.htm">2015年移动互联网与支付</a><br><a target="_blank" rel="noopener" href="https://www.moe.gov.cn/srcsite/A15/s3265/202003/t20200306_428194.html">2020年疫情与求职</a></p></div>`;$('closeCredits').onclick=()=>{$('sources').style.display='none';if(!wasPaused)pause(false);};}

// One life, from 1978 to 2026. Context stays in the small date and one sentence.
function scrubHot(actor,label,id,onProgress,onFinish,axis='x',pixels=180){let active=false,start=0,k=0;let b=hot(actor,label,id,()=>auto());b.dataset.gesture='drag';function auto(){if(active||paused||busy||cam)return;active=true;let t=time;anim.push({tick(now){if(!active)return true;k=clamp((now-t)/1.8);onProgress(k);if(k===1){active=false;onFinish();return true;}return false;}});}b.onpointerdown=e=>{if(paused||busy||cam)return;e.preventDefault();b.setPointerCapture(e.pointerId);active=true;k=0;start=axis==='x'?e.clientX:e.clientY;b.style.cursor='grabbing';};b.onpointermove=e=>{if(!active)return;let v=axis==='x'?e.clientX:e.clientY;k=clamp(Math.abs(v-start)/Math.min(pixels,innerWidth*.3));onProgress(k);if(k>=1){active=false;b.style.cursor='pointer';onFinish();}};b.onpointerup=e=>{e.preventDefault();active=false;b.style.cursor='pointer';if(k<1)hint('保持按住，再慢慢拖动。');};b.onpointercancel=()=>active=false;b.onclick=e=>{if(e.detail===0)auto();};return b;}
function schoolScene(){mode='school';corridor(12,25);lightBeam(V(-4,4,-4),V(1,-.5,2),1.6);let seats=[];for(let row=0;row<4;row++)for(let col=0;col<5;col++){let a=[];for(let i=0;i<550;i++)a.push((rand()-.5)*1.5+col*2.2-4.4,.4+rand()*.04,-row*3-5+(rand()-.5));let p=points(a,GOLD,.022);p.userData.alpha=.3;seats.push(p);}let lamp=form('lamp',-3.8,1.8,-2,2.6,GOLD,4200),book=form('book',0,.9,1,4.4,GOLD,10000),pencil=form('pencil',2.5,.5,2,2.5,GOLD,4000);let road=glyph('路',0,2,-5,3.8,GOLD);road.userData.alpha=0;book.rotation.y=-.45;let opened=false,written=false;hot(book,'翻开','open-book',()=>{if(opened)return;opened=true;sound('paper');tween(book.rotation,{y:0},2);fly(V(0,2,7),V(0,1.1,0),3);say('那时，一本书也能装下一条出路。');hint('按住笔，拖动。写下这一笔。');hotspots.find(h=>h.b.dataset.action==='open-book').b.style.display='none';},-.6);scrubHot(pencil,'写下','write-path',k=>{if(!opened)return;pencil.position.x=2.5-k*4;pencil.rotation.z=k*.25;road.userData.alpha=k*.7;lamp.userData.alpha=.65+k*.2;},()=>{if(!opened){say('先翻开那本书。');return;}if(written)return;written=true;hideHot();sound('paper');say('“读下去，往外走。”');hint('家人的希望，也成了你的责任。');let thread=[];for(let i=0;i<5500;i++){let z=rand()*18-17;thread.push(Math.sin(z*.3)*.7,-.5+rand()*.08,z);}let p=points(thread,GOLD,.03);reveal(p,3);morph(pencil,'case',V(0,1,-6),2.8,4);fly(V(-1,1.6,8),V(0,1,-7),4,()=>choices([['走向远方',()=>next(2)]]));},'x',200);camera.position.set(0,2.6,12);look.set(0,1,-3);fly(V(0,2,9),V(0,1.3,-2),4);say('书页旧了，希望还在。');hint('点击书本。');}
function workScene(){mode='work';corridor(18,40,0xbaae94);lightBeam(V(6,6,-12),V(-5,-1,2),2,0xcebf9c);let gears=[],conveyor=[];for(let k=0;k<5;k++){let a=[];for(let i=0;i<3600;i++){let angle=rand()*Math.PI*2,r=1.1+(Math.sin(angle*13)>.1?.35:.18)*rand();a.push(Math.cos(angle)*r,Math.sin(angle)*r,(rand()-.5)*.18);}let p=points(a,0xccb186,.037);p.position.set((k-2)*4,2.7,-9);gears.push(p);}for(let i=0;i<11000;i++)conveyor.push((rand()-.5)*24,-.3+rand()*.18,rand()*9-9);let belt=points(conveyor,GOLD,.023);belt.userData.alpha=.35;let staff=[];for(let i=0;i<5;i++){let p=form('person',(i-2)*3.4,1,-12,3.5,0xbeaf92,4300);p.userData.alpha=.3;staff.push(p);}let badge=form('badge',1,.7,2,2.8,GOLD,7000),hand=form('hand',1,-.1,2,2.9,GOLD,6500);hand.userData.alpha=.2;let running=true,punched=false;anim.push({tick(t){if(running){gears.forEach((p,i)=>p.rotation.z=t*(i%2?-.32:.32));belt.position.x=Math.sin(t*.3)*2;}return false;}});hot(badge,'打卡','punch-work',()=>{if(punched)return;punched=true;hideHot();busy=true;reveal(hand,1);move(badge,V(0,1,-5),2);fly(V(-1,1.7,5),V(0,1.3,-9),4);sound('stamp');after(2.8,()=>{running=false;musicLevel(.03,1);sound('dull');staff.forEach(p=>tween(p.userData,{scatter:.5,alpha:.03},4));gears.forEach(p=>tween(p.userData,{scatter:.8,alpha:.06},4));tween(belt.userData,{alpha:.03},3);say('这一次，工牌换不来工资。');hint('这段经历，来自一个虚构的受改革影响家庭。');});after(6.5,()=>{busy=false;musicLevel(.27,3);say('身份突然不稳了。明天还得继续。');hint('选一个方向，重新开始。');choices([['找一份新工作',()=>restartWork('job')],['学一门手艺',()=>restartWork('skill')]]);});},-1);function restartWork(path){busy=true;st.workPath=path;choices([]);sound('paper');morph(badge,path==='skill'?'pencil':'letter',V(0,.8,-2),3,4);tween(hand.userData,{scatter:.35,alpha:.12},3);memoryWord('重新开始',0,3,-7,5);fly(V(0,2,9),V(0,1,-3),5,()=>{busy=false;say(path==='skill'?'从靠一张工牌，到靠自己的手艺。':'从等单位安排，到自己寻找机会。');hint('那句“找个稳定的”，有时从这里长出来。');choices([['成家以后',()=>next(4)]]);});}camera.position.set(0,1.7,13);look.set(0,1.6,-8);fly(V(0,1.7,8),V(0,1.8,-8),4);say('上班、领工资。以为可以一直这样。');hint('把工牌递向打卡处。');}
function familyScene(){mode='family';corridor(13,24);lightBeam(V(3,3.5,-6),V(0,-.5,1),1.2);let parent=form('person',-4,1.1,-7,4.7,GOLD,7800),child=form('person',3.4,.3,-5,2.9,GOLD,6000),book=form('book',3.4,-.1,-3,2.2,GOLD,4800),clock=form('clock',-3,1.3,-3,2.8,GOLD,6000);let lights=[];for(let i=0;i<3;i++){let a=[];for(let j=0;j<650;j++){let angle=rand()*Math.PI*2,r=rand()*.16;a.push(Math.cos(angle)*r,Math.sin(angle)*r,(rand()-.5)*.1);}let p=points(a,GOLD,.04);p.position.set((i-1)*.65,3,-3);lights.push(p);}let evening=3,money=0,together=0;let city=[];for(let i=0;i<8000;i++){let x=(rand()-.5)*28;city.push(x,rand()*(2+(Math.floor(x+14)*13%6)),-16);}let jobs=points(city,GOLD,.018);jobs.userData.alpha=.23;after(3,()=>tween(jobs.userData,{alpha:.09,scatter:.12},4));function spend(what){if(!evening)return;busy=true;evening--;let lamp=lights[evening];tween(lamp.userData,{scatter:.7,alpha:0},2);clock.rotation.z-=.45;if(what==='work'){money++;sound('step');move(parent,V(-6,1,-9),1.5);let cash=form('money',-4,.8,-4,1.4,GOLD,600);move(cash,V(3.4,.1,-3),2.2,()=>tween(cash.userData,{alpha:.1},1));say('多一份收入，少一段陪伴。');}else{together++;sound('paper');move(parent,V(1.1,.8,-5),1.8);child.userData.alpha=.7;let warmth=[];for(let i=0;i<2300;i++){let a=rand()*Math.PI*2,r=Math.sqrt(rand())*1.7;warmth.push(2.1+Math.cos(a)*r,.4+Math.sin(a)*r,-5+(rand()-.5));}reveal(points(warmth,0xf5ca8c,.027),2);say('这一个晚上，留给孩子。');}after(2.8,()=>{busy=false;if(evening){hint('还有 '+evening+' 个晚上。收入与陪伴，都有重量。');}else{st.parenting={money,together};save();hideHot();say(together?'“愿你以后，有更多选择。”':'你撑住了开支。孩子也在等你。');hint('每一种选择，都有没能兼顾的东西。');choices([['再过几年',()=>next(6)]]);}});}hot(clock,'加班','family-work',()=>spend('work'),-1.1);hot(book,'陪孩子','family-time',()=>spend('time'),-.7);camera.position.set(0,2,12);look.set(0,1,-5);fly(V(0,1.8,9),V(0,1,-4),4);say('白天要挣钱，晚上还想陪他。');hint('三个晚上，逐个决定留给谁。');}
function digitalScene(){mode='digital';let parent=form('person',-4,1,-7,4.6,GOLD,7000),young=form('person',4,1,-7,3.7,BLUE,6000),phone=form('phone',0,.9,-1,4.5,BLUE,8200),hand=form('hand',-1,-.5,1,2.8,GOLD,6500);hand.rotation.z=.3;let code=[];for(let y=0;y<29;y++)for(let x=0;x<29;x++){let finder=(x<7&&y<7)||(x>21&&y<7)||(x<7&&y>21);if(finder||rand()>.52)for(let j=0;j<5;j++)code.push((x-14)*.039+(rand()-.5)*.018,.9+(14-y)*.039+(rand()-.5)*.018,-.92+(rand()-.5)*.025);}let qr=points(code,BLUE,.044);let scan=[];for(let i=0;i<1400;i++)scan.push((rand()-.5)*1.5,0,(rand()-.5)*.025);let beam=points(scan,0xd1ecdf,.033);beam.position.set(0,1.5,-.8);beam.userData.alpha=0;let scanned=false;let scanButton=scrubHot(phone,'往下扫','learn-phone',k=>{beam.userData.alpha=.7;beam.position.y=1.55-k*1.3;hand.position.y=-.5+k*.5;qr.userData.alpha=.45+k*.4;},()=>{if(scanned)return;scanned=true;hideHot();sound('off');tween(beam.userData,{alpha:0},1.5);tween(qr.userData,{scatter:.4,alpha:0},2);let pulse=[];for(let i=0;i<5000;i++){let x=(rand()-.5)*8;pulse.push(x,1+Math.sin(x*.8)*.4,-4+(rand()-.5)*.1);}let p=points(pulse,GOLD,.029);reveal(p,2.5);say('“这次，你教我一下。”');hint('曾经牵你的手，也会有跟不上的时候。');fly(V(-2,1.8,8),V(0,1,-3),4,()=>choices([['继续往后走',()=>next(7)]]));},'y',140);camera.position.set(0,1.8,12);look.set(0,1,-3);fly(V(0,1.7,8),V(0,1,-2),4);say('小小的屏幕，像一扇陌生的门。');hint('按住手机上的字，向下拖动。');}
function pandemicScene(){mode='pandemic';lightBeam(V(-3,4,-16),V(2,-.5,4),1.5,BLUE);let window=form('window',0,1,-1,7,GOLD,14000);window.userData.alpha=.45;let city=[];for(let i=0;i<17000;i++){let x=(rand()-.5)*36,h=2+(Math.floor(x+18)*17%10);city.push(x,rand()*h-1,-18+(rand()-.5)*3);}let distant=points(city,0x718e97,.022);distant.userData.alpha=.2;let route=[];for(let i=0;i<8000;i++){let z=rand()*22-14;route.push(Math.sin(z*.24)*2,-1.1+rand()*.04,z);}let road=points(route,GOLD,.024);road.userData.alpha=.22;after(2,()=>tween(road.userData,{scatter:.6,alpha:0},4));let phone=form('phone',-3,.6,2,2.9,BLUE,5500),bowl=form('bowl',0,-.1,3,2.3,GOLD,5000),cash=form('money',3,.3,2,2.1,GOLD,2600);let done=new Set();function check(){if(done.size<3)return;hideHot();say('被打断的计划，要重新接起来。');hint('孩子也经历着同一场不确定。');choices([['走到今天',()=>next(8)]]);}hot(phone,'联系家人','check-family',()=>{if(done.has('call'))return;done.add('call');sound('dial');let hand=form('hand',-3,.2,-12,3.3,GOLD,5000);reveal(hand,3);let thread=[];for(let i=0;i<4500;i++){let k=rand();thread.push(-3,1+Math.sin(k*Math.PI)*1.5,2-k*14);}let p=points(thread,BLUE,.027);reveal(p,2);say('“你那边，还好吗？”');phone.userData.alpha=.3;hotspots.find(h=>h.b.dataset.action==='check-family').b.style.display='none';check();},-1);hot(bowl,'今天的饭','today-meal',()=>{if(done.has('meal'))return;done.add('meal');busy=true;sound('grain');pour(V(.2,1.2,3),V(0,.05,3),650,1.2,()=>{busy=false;hotspots.find(h=>h.b.dataset.action==='today-meal').b.style.display='none';say('日子暂时慢了，饭还要一顿顿做。');check();});},-.8);hot(cash,'明天的开支','keep-reserve',()=>{if(done.has('money'))return;done.add('money');sound('coin');move(cash,V(2.3,.2,1),2);say(st.path==='margin'?'从前留的一点余量，现在接住了生活。':'账单不会暂停。先把开支排清楚。');hotspots.find(h=>h.b.dataset.action==='keep-reserve').b.style.display='none';check();},-1);camera.position.set(0,1.7,12);look.set(0,1,-5);fly(V(0,1.7,8),V(0,1,-5),4);say('远方，突然去不了了。');hint('联系家人，照顾今天，留出明天。');}

const scoreFiles=['score-memory','score-tension','score-change','score-after'];
const scoreTitles=['Signal to Noise','Signal to Noise · No Piano Melody','Undertow','Penumbra'];
let ac=null,bus=null,musicOut=null,audioMeter=null,recordDest=null,tracks=[],trackGains=[],current=-1,musicTarget=.3,sfxActive=new Set();
function initAudio(){if(ac){ac.resume();return;}ac=new(window.AudioContext||window.webkitAudioContext)();let limiter=ac.createDynamicsCompressor(),mixLift=ac.createGain();mixLift.gain.value=2.8;mixLift.connect(limiter);limiter.threshold.value=-5;limiter.knee.value=8;limiter.ratio.value=8;limiter.attack.value=.006;limiter.release.value=.28;audioMeter=ac.createAnalyser();audioMeter.fftSize=2048;limiter.connect(audioMeter);audioMeter.connect(ac.destination);recordDest=ac.createMediaStreamDestination();limiter.connect(recordDest);bus=ac.createGain();bus.gain.value=.65;bus.connect(mixLift);musicOut=ac.createGain();musicOut.gain.value=.3;musicOut.connect(mixLift);for(let i=0;i<scoreFiles.length;i++){let a=new Audio(window.LOCAL_SCORES?.[i]||'assets/'+scoreFiles[i]+'.mp3');a.loop=true;a.preload='metadata';a.volume=1;let source=ac.createMediaElementSource(a),gain=ac.createGain();gain.gain.value=0;source.connect(gain).connect(musicOut);tracks.push(a);trackGains.push(gain);}ac.resume();}
function gainTo(param,value,seconds){if(!ac)return;let t=ac.currentTime;param.cancelScheduledValues(t);param.setValueAtTime(param.value,t);param.linearRampToValueAtTime(value,t+seconds);}
function musicLevel(level,seconds=2){musicTarget=level;if(musicOut)gainTo(musicOut.gain,muted?0:level,seconds);}
function score(i,at=0,level=.32){if(!ac)return;let old=current;current=i;tracks[i].currentTime=at;tracks[i].play().catch(()=>{});musicLevel(level,2.5);trackGains.forEach((g,j)=>gainTo(g.gain,j===i?1:0,j===i?3:2.6));after(3.2,()=>{if(current===i)tracks.forEach((a,j)=>{if(j!==i)a.pause();});});}
function recorded(type,volume=.35,pan=0){if(!ac||muted||paused)return false;let name={wind:'transition',dull:'change',off:'notification',answer:'dial'}[type]||type;if(!['paper','dial','train','transition','change','click','notification','ring','rail'].includes(name))return false;let a=new Audio(window.LOCAL_SFX?.[name]||'assets/sfx/'+name+'.mp3');a.volume=1;let src=ac.createMediaElementSource(a),g=ac.createGain(),p=ac.createStereoPanner();g.gain.value=volume;p.pan.value=pan;src.connect(g).connect(p).connect(bus);sfxActive.add(a);a.onended=()=>{src.disconnect();g.disconnect();p.disconnect();sfxActive.delete(a);};a.onerror=a.onended;a.play().catch(()=>a.onended());return true;}
