if(type==='letter'){q.lineWidth=5;q.strokeRect(62,146,388,238);q.moveTo(62,146);q.lineTo(256,283);q.lineTo(450,146);q.moveTo(62,384);q.lineTo(196,271);q.moveTo(450,384);q.lineTo(312,270);q.stroke();}
