function loop(now){requestAnimationFrame(loop);let dt=last?Math.min((now-last)/1000,.3):0;last=now;if(paused)return;time+=dt;if(cam){let c=cam,k=clamp((time-c.start)/c.dur),e=k*k*(3-2*k);camera.position.lerpVectors(c.a,c.b,e);camera.position.y+=Math.sin(k*Math.PI)*.12;look.lerpVectors(c.c,c.d,e);if(k>=1){cam=null;if(c.done)c.done();}}camera.lookAt(look);let previous=anim;anim=[];previous.forEach(a=>{if(!a.tick(time))anim.push(a);});ambient.rotation.y=time*.001;actors.forEach(p=>{p.material.uniforms.uTime.value=time;p.material.uniforms.uOpacity.value=p.userData.alpha;p.material.uniforms.uScatter.value=p.userData.scatter;});scene.updateMatrixWorld();hotspots.forEach(h=>{let p=h.actor.position.clone();p.y+=h.dy;p.project(camera);h.b.style.left=clamp((p.x*.5+.5)*innerWidth,innerWidth*.12,innerWidth*.88)+'px';h.b.style.top=clamp((-p.y*.5+.5)*innerHeight,innerHeight*.28,innerHeight*.72)+'px';h.b.style.visibility=p.z<0||p.z>1?'hidden':'visible';});renderer.render(scene,camera);}
